contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that deposit(assets, receiver) only succeeds when msg.sender == receiver (withApproval)
    // and when it succeeds it returns the shares value produced by the investmentManager.processDeposit call.
    // Since we cannot directly observe the investmentManager internal return aside from the function return,
    // we check the following general property: if this contract calls deposit with receiver==address(this),
    // the call must NOT revert and must return a uint256 shares; moreover, after the call totalAssets() is
    // consistent (i.e., non-negative) and the returned shares equals the function return value (trivially).
    // The meaningful universal property we assert: when receiver == address(this), deposit must not revert.

    function run(uint256 assets, address receiver) public payable {
        require(address(this) == receiver || receiver != receiver, "precondition"); // no-op to keep param used
        // We will attempt deposit both with receiver == address(this) and receiver != address(this).
        bool reverted;
        uint256 returnedShares = type(uint256).max;
        if (receiver == address(this)) {
            // when receiver equals msg.sender (this contract), deposit must succeed (not revert)
            reverted = false;
            try c.deposit(assets, receiver) returns (uint256 shares) {
                returnedShares = shares;
            } catch {
                reverted = true;
            }
        } else {
            // when receiver != msg.sender, deposit should revert due to withApproval modifier
            reverted = false;
            try c.deposit(assets, receiver) returns (uint256 shares) {
                returnedShares = shares;
            } catch {
                reverted = true;
            }
        }

        // General rule asserted:
        // If receiver == address(this) then the call must NOT revert. If receiver != address(this) then the call must revert.
        // This captures the withApproval modifier requirement that msg.sender == owner.
        assert((receiver == address(this) && reverted == false) || (receiver != address(this) && reverted == true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising deposit which uses the withApproval(owner) modifier.
    // We call deposit exactly twice as top-level statements: once with receiver == address(this)
    // and once with receiver != address(this) (if possible). We catch reverts and assert the general rule:
    // deposit succeeds iff receiver == msg.sender.
    function run(uint256 assets, address receiver) public payable {
        // No precondition on c. Ensure receiver param is used even if equal to address(this).
        require(address(this) != address(0));

        bool reverted1;
        bool reverted2;
        uint256 out1;
        uint256 out2;

        // First call: with receiver == address(this)
        // We must call as a top-level statement. Use try/catch to capture revert.
        reverted1 = false;
        try c.deposit(assets, address(this)) returns (uint256 shares) {
            out1 = shares;
        } catch {
            reverted1 = true;
        }

        // Second call: with receiver == receiver param (may equal address(this) as well)
        reverted2 = false;
        try c.deposit(assets, receiver) returns (uint256 shares2) {
            out2 = shares2;
        } catch {
            reverted2 = true;
        }

        // General rule: deposit must succeed exactly when msg.sender == owner (i.e., receiver == address(this)).
        // Therefore: first call (owner==address(this)) must NOT revert. Second call must revert iff receiver != address(this).
        assert((reverted1 == false) && ( (receiver == address(this) && reverted2 == false) || (receiver != address(this) && reverted2 == true) ));
    }

    receive() external payable {}
}

