contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: take parameters for deposit flow
    function run(uint256 assets, uint256 shares, address receiver, bool doDeposit) public payable {
        require(receiver != address(0) && receiver != address(this));

        // Read pre-state observables
        uint256 totalAssetsBefore = c.totalAssets();
        uint256 totalSupplyBefore = c.totalSupply();

        // Use preview functions to observe expected conversions from caller's perspective
        uint256 previewShares = c.previewDeposit(assets);
        uint256 previewAssetsForMint = c.previewMint(shares);

        bool reverted;
        uint256 returnedValue;

        // Call either deposit or mint using withApproval(receiver) (msg.sender is this contract)
        if (doDeposit) {
            // deposit has signature deposit(uint256,address)
            try c.deposit(assets, receiver) returns (uint256 s) {
                reverted = false;
                returnedValue = s;
            } catch {
                reverted = true;
                returnedValue = 0;
            }
        } else {
            // mint(uint256,address)
            try c.mint(shares, receiver) returns (uint256 a) {
                reverted = false;
                returnedValue = a;
            } catch {
                reverted = true;
                returnedValue = 0;
            }
        }

        // Read post-state observables
        uint256 totalAssetsAfter = c.totalAssets();
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule asserted:
        // - If the call reverted, global assets/supply must be unchanged.
        // - If call succeeded and was deposit: returned shares should be >= previewDeposit(assets) (investment manager may round up),
        //   and totalAssetsAfter must be >= totalAssetsBefore when assets>0.
        // - If call succeeded and was mint: returned assets should be >= previewMint(shares),
        //   and totalSupplyAfter must be >= totalSupplyBefore when shares>0.
        assert(
            (reverted && totalAssetsAfter == totalAssetsBefore && totalSupplyAfter == totalSupplyBefore)
            || (
                !reverted && (
                    (doDeposit && returnedValue >= previewShares && (assets == 0 || totalAssetsAfter >= totalAssetsBefore))
                    || (!doDeposit && returnedValue >= previewAssetsForMint && (shares == 0 || totalSupplyAfter >= totalSupplyBefore))
                )
            )
        );
    }

    receive() external payable {}
}

