            try c.deposit(assets, receiver) returns (uint256 s) {
                reverted = false;
                returned = s;
            } catch {
                reverted = true;
                returned = 0;
            }
        } else {
            // mint(uint256,address) returns (uint256 assets)
            try c.mint(shares, receiver) returns (uint256 a) {
                reverted = false;
                returned = a;
