contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be checked for the property
    function run(address caller, uint128 price) public payable {
        require(caller != address(0), "bad caller");

        // Ensure this contract is authorized to call auth-only functions on c.
        // The constructor of C gives wards[msg.sender] = 1 where msg.sender was deployer of C.
        // In the test environment, InvMutTest deployed C, so InvMutTest (this) is authorized already.
        // But to exercise both authorized and unauthorized cases we branch by using `caller`:
        // If caller == address(this) we will perform the update directly (authorized),
        // otherwise we attempt to call via a low-level call from a different address by
        // simulating failure: since we cannot change msg.sender here, we treat that
        // attempting to call updatePrice via c.updatePrice(...) will either succeed
        // (if this contract is authorized) or revert (if not). To get an unauthorized
        // attempt we require the provided caller to be different from this contract and
        // then attempt the call via the public function of c but expect revert.

        // Read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool reverted;
        // Decide which actor to test: if caller == address(this) test successful auth call,
        // otherwise test that a call with this contract (which may or may not be authorized)
        // when impersonating the other caller cannot be performed here; instead we use the
        // provided caller value to select expected outcome: if caller == address(this) expect success,
        // else expect that updatePrice either reverts or, if this contract happens to be authorized,
        // still sets the price. We capture the actual behavior via try/catch.
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule to assert:
        // If the call did not revert, then latestPrice must equal the provided price and lastPriceUpdate
        // must be >= before timestamp (i.e., advanced or equal) and must be <= block.timestamp.
        // If the call reverted, then latestPrice and lastPriceUpdate must be unchanged.
        // This connects revert behavior to observable state changes.
        assert(
            (!reverted && afterPrice == price && afterTs >= beforeTs && afterTs <= block.timestamp)
            || (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    // receive fallback to accept Ether if needed by environment
    receive() external payable {}
}

