contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call mint on c with varying (user, amount). We check effect on totalSupply.
    function run(address user, uint256 amount) public payable {
        require(user != address(0), "nonzero user");
        // Observe totalSupply before
        uint256 before = c.totalSupply();

        bool reverted;
        // Call c.mint(user, amount) and capture revert status. This call requires auth; in most cases it will revert.
        try c.mint(user, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint256 after = c.totalSupply();

        // General property: totalSupply never decreases; if mint reverted then totalSupply unchanged.
        assert(after >= before && (reverted ? after == before : true));
    }

    receive() external payable {}
}

