contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller (this contract) is authorized at deployment of C
    // parameters: newManager (address to set), caller (address which will attempt to call file)
    function run(address newManager, address caller) public payable {
        require(newManager != address(0) && caller != address(0));

        // Ensure that this contract is authorized: constructor of C sets deployer as ward, and
        // InvMutTest was used to deploy C in the checker setup per instructions.
        // We observe behavior when an authorized and unauthorized caller invoke file.

        // First, record current investmentManager
        address before = address(c.investmentManager());

        bool reverted;
        // If caller equals address(this), we call directly; otherwise we simulate a call from caller
        // by using file through c.call with encoded calldata, because we cannot change msg.sender.
        // For the checker's model, msg.sender for calls from this contract will always be InvMutTest;
        // to test unauthorized behavior we compare two calls made by this contract: one expecting success
        // (when this contract is authorized) and one expecting revert when not authorized. Since only
        // wards[msg.sender] matters and only the C constructor authorized its deployer, we cannot
        // change wards here. So we test that when this contract calls file it succeeds and sets manager.

        // Attempt to set investmentManager to newManager
        try c.file("investmentManager", newManager) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = address(c.investmentManager());

        // General rule: if the call did not revert then the investmentManager getter returns newManager;
        // if it reverted then investmentManager remains unchanged.
        assert( (reverted && after == before) || (!reverted && after == newManager) );
    }

    receive() external payable { }
 }

