contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests updatePrice behavior
    // params: caller (address to become authorized via rely), price to set
    function run(address caller, uint128 price) public payable {
        require(caller != address(0), "invalid-caller");

        // Initially, the deploying test contract (this) is warded because C's constructor calls rely(msg.sender)
        // So we can call rely to authorize `caller`.
        c.rely(caller);

        // read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // attempt to call updatePrice as the authorized `caller` by invoking via low-level call from this contract.
        // To simulate calls from `caller`, we use transfer of authorization: we rely'd caller so it is authorized, but
        // the checker runs this single transaction with msg.sender = this contract. We cannot change msg.sender.
        // Instead, we check the rule in two parts:
        // 1) calling updatePrice from this contract (which is authorized) must set latestPrice to price and update timestamp.
        // 2) calling updatePrice from an unauthorized address would revert — we detect that by first denying this contract and
        //    then attempting the call and observing revert.

        // Part 1: this contract is authorized (constructor of C set wards[this]=1). Ensure it's authorized by calling rely on itself
        // (note: rely can only be called by an authorized ward; this contract is authorized initially)
        c.rely(address(this));

        bool revertedWhenThisCalled;
        try c.updatePrice(price) {
            revertedWhenThisCalled = false;
        } catch {
            revertedWhenThisCalled = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // Part 2: ensure unauthorized callers revert. Deny this contract, then try calling updatePrice (should revert now).
        c.deny(address(this));
        bool revertedAfterDeny;
        try c.updatePrice(price + 1) {
            revertedAfterDeny = false;
        } catch {
            revertedAfterDeny = true;
        }

        // General property asserted:
        // - If updatePrice did not revert when called by this contract (meaning it was authorized), then latestPrice must equal the argument
        //   and lastPriceUpdate must have increased to a nonzero value (>= beforeTimestamp, but timestamp monotonicity cannot be strictly assumed
        //   across EVM semantics in a single tx, so we assert it's nonzero and different if before was zero).
        // - Also, after denying this contract, calling updatePrice must revert.

        assert(((!revertedWhenThisCalled && afterPrice == price && (afterTimestamp != 0 && (beforeTimestamp == 0 || afterTimestamp >= beforeTimestamp)))
                && revertedAfterDeny)
               || (revertedWhenThisCalled && !revertedAfterDeny == false));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests updatePrice authorization and effects
    // params: addrToAuthorize - address to grant then revoke authorization; price - value to set
    function run(address addrToAuthorize, uint128 price) public payable {
        require(addrToAuthorize != address(0), "zero-addr");

        // The deployer of C (the test harness that constructed c) was set as ward in C's constructor.
        // So this contract (msg.sender of those calls to c) is currently authorized and can call rely/deny.

        // Authorize addrToAuthorize
        c.rely(addrToAuthorize);

        // Read pre-state
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Attempt to update price as the current authorized caller (this contract). This should succeed because this
        // contract is authorized (it constructed c) and we have not denied it.
        bool succeededWhenThisCalled;
        try c.updatePrice(price) {
            succeededWhenThisCalled = true;
        } catch {
            succeededWhenThisCalled = false;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // Revoke this contract's authorization
        c.deny(address(this));

        // After deny, calling updatePrice should revert when attempted by this contract
        bool revertedAfterDeny;
        try c.updatePrice(uint128(price + 1)) {
            revertedAfterDeny = false;
        } catch {
            revertedAfterDeny = true;
        }

        // Assert the general rule:
        // If the call by this contract succeeded then latestPrice equals the argument given and lastPriceUpdate is nonzero
        // (and is not decreased below a previous nonzero timestamp). Also, after deny the same caller's updatePrice must revert.
        // We avoid assuming strict timestamp monotonicity across txs; we require non-decrease when beforeTs != 0.
        assert(
            (succeededWhenThisCalled
                ? (afterPrice == price && afterTs != 0 && (beforeTs == 0 || afterTs >= beforeTs) && revertedAfterDeny)
                : revertedAfterDeny /* if the initial call somehow reverted, at least we still require that after deny it reverts */)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry testing mint behavior and its authorization: caller is this contract
    // params: target - address to be minted to (must be non-zero), amount - amount to mint
    function run(address target, uint256 amount) public payable {
        require(target != address(0), "zero-target");

        // At deployment of C in the harness, this contract was granted auth (wards[msg.sender]=1).
        // Read totalSupply before mint attempt
        uint256 supplyBefore = c.totalSupply();

        // Try calling mint as an authorized caller. Capture whether it reverts.
        bool succeededBeforeDeny;
        try c.mint(target, amount) {
            succeededBeforeDeny = true;
        } catch {
            succeededBeforeDeny = false;
        }

        // Read totalSupply after the call
        uint256 supplyAfter = c.totalSupply();

        // Revoke this contract's authorization
        c.deny(address(this));

        // After deny, mint by this contract must revert
        bool revertedAfterDeny;
        try c.mint(target, amount) {
            revertedAfterDeny = false;
        } catch {
            revertedAfterDeny = true;
        }

        // General rule asserted:
        // - If the initial mint call succeeded externally then either the totalSupply increased (supplyAfter >= supplyBefore)
        //   or the increase is not observable via totalSupply() (some implementations may not change totalSupply on success),
        //   but we require that supplyAfter is >= supplyBefore. If the call reverted, supply must be unchanged.
        // - And after revoke, mint must revert for this caller.
        assert(
            (
                succeededBeforeDeny
                    ? (supplyAfter >= supplyBefore)
                    : (supplyAfter == supplyBefore)
            )
            && revertedAfterDeny
        );
    }

    receive() external payable {}
}

