contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driven by inputs
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // read a preview and totalAssets before calling
        uint256 previewBefore = c.previewDeposit(assets);
        uint256 totalAssetsBefore = c.totalAssets();

        // attempt the deposit and capture revert status and returned shares
        bool reverted;
        uint256 returnedShares = type(uint256).max; // sentinel
        try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        // After call read observable values
        uint256 previewAfter = c.previewDeposit(assets);
        uint256 totalAssetsAfter = c.totalAssets();

        // General rule:
        // If deposit did not revert then returnedShares must be a finite value
        // and must be >= previewBefore (i.e., processDeposit should not return fewer shares than preview indicates),
        // and the totalAssets may only increase or stay the same.
        assert(
            reverted || (
                returnedShares != type(uint256).max
                && returnedShares >= previewBefore
                && totalAssetsAfter >= totalAssetsBefore
            )
        );
    }

    receive() external payable {}
}

