contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try both authorized and unauthorized caller behavior
    // params: callerIsAuth - if true, we first make this contract authorized by calling rely via c (constructor made deployer ward)
    // price - the price to set
    function run(bool callerIsAuth, uint128 price) public payable {
        require(true);

        // The initial deployer (the test runner) is not the ward in the fresh c; the contract that deployed c is ward.
        // We cannot change msg.sender for calls, but InvMutTest is the msg.sender when calling c.
        // To become authorized we must have the ward set to this contract's address. The only way is if the deployer of c
        // set wards[this] during c construction. That is not generally true, so calling updatePrice should revert for unauthorized.
        // But the contract C exposes rely/deny only to auth; we cannot gain auth if not already authorized. Therefore we
        // attempt updatePrice and record whether it reverted. If callerIsAuth is true we first check if c.wards(address(this)) == 1
        // by observing revert behavior of updatePrice: if the call succeeds, latestPrice must equal price and lastPriceUpdate > 0.

        bool reverted;
        // perform the call and catch revert
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 latest = c.latestPrice();
        uint256 lastTs = c.lastPriceUpdate();

        // General rule: if the call did not revert then latestPrice equals price and lastPriceUpdate is nonzero and lastPriceUpdate <= block.timestamp (can't observe block.timestamp here),
        // but we can check nonzero. If the call reverted then latestPrice and lastPriceUpdate remain as before the call OR at least the call did not set latestPrice to price.
        // We cannot read previous values easily after the call, but we can assert the implication: not reverted => latest==price && lastTs != 0
        // Additionally, if reverted then latest != price OR lastTs == 0 (this avoids needing previous values). This yields a general partition.

        assert((!reverted && latest == price && lastTs != 0) || (reverted && (latest != price || lastTs == 0)));
    }

    receive() external payable {}
}

