contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params:
    // assets: amount to deposit
    // receiver: address to receive shares (must be this contract to satisfy withApproval when used)
    function run(uint256 assets, address receiver) public payable {
        require(receiver == address(this), "test requires receiver==this to satisfy withApproval");

        // Read observable before-state
        uint256 beforeTotalAssets = c.totalAssets();

        // Compute preview via view call as the canonical expected shares for a deposit
        uint256 expectedShares = c.previewDeposit(assets);

        // Try the state-changing deposit call and capture revert
        bool reverted;
        uint256 returnedShares;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
            returnedShares = 0;
        }

        // After-state observation
        uint256 afterTotalAssets = c.totalAssets();

        // General property asserted:
        // - If the call reverted, totalAssets must be unchanged (no partial side-effect allowed).
        // - If the call succeeded, the returned shares must equal the previewDeposit(assets) computed before the call,
        //   and totalAssets must be >= beforeTotalAssets (assets added cannot decrease total assets).
        assert(
            (reverted && afterTotalAssets == beforeTotalAssets) ||
            (!reverted && returnedShares == expectedShares && afterTotalAssets >= beforeTotalAssets)
        );
    }

    receive() external payable {}
}

