        // preconditions about addresses: receiver and owner can be any addresses, allow zero.

        // Read conversion helpers before doing state-changing call.
        uint256 conv1_before = c.convertToShares(a);
        uint256 conv2_before = c.convertToAssets(a);

        bool reverted;
        uint256 returnedValue = 0;

        if (opKind == 0) {
            // deposit(uint256 assets, address receiver) returns (uint256 shares)
            try c.deposit(a, receiver) returns (uint256 shares) {
                reverted = false;
                returnedValue = shares;
            } catch {
                reverted = true;
            }
        } else if (opKind == 1) {
            // mint(uint256 shares, address receiver) returns (uint256 assets)
            try c.mint(a, receiver) returns (uint256 assets) {
                reverted = false;
                returnedValue = assets;
            } catch {
                reverted = true;
            }
        } else if (opKind == 2) {
            // withdraw(uint256 assets, address receiver, address owner) returns (uint256 shares)
            try c.withdraw(a, receiver, owner) returns (uint256 shares) {
                reverted = false;
                returnedValue = shares;
            } catch {
                reverted = true;
            }
        } else {
            // redeem(uint256 shares, address receiver, address owner) returns (uint256 assets)
            try c.redeem(a, receiver, owner) returns (uint256 assets) {
                reverted = false;
                returnedValue = assets;
            } catch {
                reverted = true;
            }
        }

