        // If the call did not revert, then returnedValue is equal to the corresponding preview or
        // conversion when that preview is available for the caller (msg.sender for preview functions is this contract).
        // We cannot call previewDeposit/previewWithdraw for other signatures if they require msg.sender matching receiver/owner,
        // but the public preview functions use msg.sender in C; we call them as this contract.

        if (!reverted) {
            if (opKind == 0) {
                // previewDeposit(uint256 assets) returns shares
                uint256 predShares = c.previewDeposit(a);
                assert(returnedValue == predShares);
            } else if (opKind == 1) {
                // previewMint(uint256 shares) returns assets
                uint256 predAssets = c.previewMint(a);
                assert(returnedValue == predAssets);
            } else if (opKind == 2) {
                // previewWithdraw(uint256 assets) returns shares
                uint256 predShares = c.previewWithdraw(a);
                assert(returnedValue == predShares);
            } else {
                // previewRedeem(uint256 shares) returns assets
                uint256 predAssets = c.previewRedeem(a);
                assert(returnedValue == predAssets);
            }
