        assert(
            // If call reverted, contract state must be unchanged for these two public vars
            (reverted && afterPrice == beforePrice && afterTime == beforeTime)
            ||
            // If call succeeded, latestPrice must equal the input and lastPriceUpdate must be >= previous value
            (!reverted && afterPrice == price && afterTime >= beforeTime)
        );
    }

    receive() external payable {}
