    C c;
    constructor(C _c) { c = _c; }

    function run(address usr, uint256 amount) public payable {
        require(usr != address(0));

        // Observe public getters before privileged calls
        address beforeAsset = c.asset();
        uint64 beforePoolId = c.poolId();
        uint256 beforeTotalSupply = c.totalSupply();

        // Attempt privileged operations and record whether they reverted
        bool mintReverted;
        try c.mint(usr, amount) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        bool burnReverted;
        try c.burn(usr, amount) {
            burnReverted = false;
        } catch {
            burnReverted = true;
        }

        // Observe public getters after calls
        address afterAsset = c.asset();
        uint64 afterPoolId = c.poolId();
        uint256 afterTotalSupply = c.totalSupply();

        // General invariant rule:
        // If either privileged call (mint or burn) did NOT revert, then the immutables asset() and poolId()
        // must remain equal to their previous values, and totalSupply() must not have decreased.
        assert((mintReverted && burnReverted) || (afterAsset == beforeAsset && afterPoolId == beforePoolId && afterTotalSupply >= beforeTotalSupply));
    }

    receive() external payable {}
}

