contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property test
    function run(uint128 price, address authorized) public payable {
        require(price != 0, "avoid trivial zero price");
        // grant authorization to this test contract's caller (authorized) by having the deploying constructor's ward rely
        // The test contract cannot call Auth.rely as it's not authorized; but constructor of C sets deployer as ward.
        // To exercise updatePrice, we need to call it from an authorized address. The checker deploys fresh C with wards[msg.sender]=1 for the deployer of C.
        // In the test environment, msg.sender for calls on c is this InvMutTest contract. So to get authorization here we rely on the constructor of C having set its deployer as ward and then the test contract being that deployer — the checker satisfies that by deploying C before this test contract's constructor.

        // Read values before
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

        // Try calling updatePrice from this contract (msg.sender will be this test contract) and record whether it reverted
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after (even if reverted, these getters are safe)
        uint128 afterPrice = c.latestPrice();
        uint256 afterTime = c.lastPriceUpdate();

        // General rule: If the call did not revert, then latestPrice must equal the provided price
        // and lastPriceUpdate must be strictly greater than beforeTime (i.e., it was updated to a nonzero timestamp >= beforeTime).
        // If the call reverted, state must be unchanged (conservative rule): both latestPrice and lastPriceUpdate unchanged.
        assert(reverted ? (afterPrice == beforePrice && afterTime == beforeTime) : (afterPrice == price && afterTime >= beforeTime && afterTime != 0));
    }

    receive() external payable {}
}

