contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address receiver, address owner, uint256 assets, uint256 shares) public payable {
        require(receiver != address(0) && owner != address(0));

        // We will test two functions protected by withApproval(owner): deposit and withdraw.
        // Because this test contract is the caller (msg.sender for calls to c), the call should
        // succeed iff owner == address(this). We observe success/failure via try/catch.

        bool depositReverted;
        uint256 depositReturnedShares = type(uint256).max;
        try c.deposit{value: 0}(assets, owner) returns (uint256 s) {
            depositReverted = false;
            depositReturnedShares = s;
        } catch {
            depositReverted = true;
        }

        bool withdrawReverted;
        uint256 withdrawReturnedShares = type(uint256).max;
        try c.withdraw{value: 0}(assets, receiver, owner) returns (uint256 s) {
            withdrawReverted = false;
            withdrawReturnedShares = s;
        } catch {
            withdrawReverted = true;
        }

        // General rule: both deposit and withdraw are protected by withApproval(owner), which requires
        // msg.sender == owner. Since this contract is msg.sender for both calls, they must either both
        // revert (when owner != address(this)) or both be allowed to proceed (when owner == address(this)).
        // If allowed to proceed, their returned values are finite uint256s (not the sentinel max value we used).
        assert((owner == address(this) && !depositReverted && !withdrawReverted && depositReturnedShares != type(uint256).max && withdrawReturnedShares != type(uint256).max)
            || (owner != address(this) && depositReverted && withdrawReverted));
    }

    receive() external payable {}
}

