contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the relationship between deposit and mint when called with receiver == msg.sender (this contract).
    // Inputs: assets and shares are arbitrary numbers. We call deposit(assets, receiver) and mint(shares, receiver)
    // with receiver == address(this). We record whether each call reverts. The invariant asserted:
    // For the same receiver (msg.sender), deposit and mint should either both succeed or both revert.
    // This checks that 'withApproval' guard (which requires msg.sender == owner) behaves consistently for these two entrypoints
    // when owner == msg.sender (so they should both be allowed) — any inconsistency indicates a bug.
    function run(uint256 assets, uint256 shares) public payable {
        address receiver = address(this);

        // Precondition: none about assets/shares
        require(true);

        bool depositReverted;
        bool mintReverted;
        // call deposit(assets, receiver) and catch revert
        try c.deposit(assets, receiver) returns (uint256 returnedShares) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // call mint(shares, receiver) and catch revert
        try c.mint(shares, receiver) returns (uint256 returnedAssets) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        // General rule: for the same receiver equal to msg.sender, deposit and mint should either both revert or both succeed.
        assert(depositReverted == mintReverted);
    }

    receive() external payable {}
}

