contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising updatePrice: price and caller-authorization via rely/deny
    function run(address maybeAuth, uint128 price) public payable {
        require(maybeAuth != address(0), "nonzero auth addr");
        // Initially, deployer (this contract) is the ward in c when c was constructed by the checker.
        // Make sure maybeAuth becomes authorized by having the current authorized ward call rely(maybeAuth).
        // msg.sender for calls to c will be this contract, so we must call c.rely(maybeAuth) from here.
        // That call requires this contract to be authorized; it will be because the checker deployed c with
        // wards[msg.sender]=1 (per C constructor comment). So this call should succeed.
        c.rely(maybeAuth);

        // Record pre-state
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Now attempt to have maybeAuth call updatePrice; simulate by calling c.updatePrice from this contract
        // but only allowed if msg.sender == maybeAuth; we cannot change msg.sender, so instead we assert two cases:
        // 1) If maybeAuth == address(this) then our call will be authorized and should succeed.
        // 2) Otherwise, calling updatePrice from here should revert (unauthorized).

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, it must have set latestPrice == price and lastPriceUpdate > beforeTs
        // If the call reverted, then state must be unchanged: latestPrice == beforePrice and lastPriceUpdate == beforeTs
        assert(
            (!reverted && c.latestPrice() == price && c.lastPriceUpdate() > beforeTs) ||
            (reverted && c.latestPrice() == beforePrice && c.lastPriceUpdate() == beforeTs)
        );
    }

    receive() external payable {}
}

