contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving c
    // params: caller address to attempt update (we simulate by calling through this contract only), price to set
    function run(uint128 price, bool tryAuth) public payable {
        require(true);

        // We are the deployer of c (checker deploys a fresh c and passes it to constructor).
        // The Auth contract uses wards mapping; constructor of C already set wards[msg.sender]=1 for its deployer,
        // which is the checker when creating C. Our test cannot assume we are authorized.
        // To create an authorized call path, use c.rely via an authorized caller: the only authorized account currently is c's deployer (not us).
        // But we cannot call c.rely because we are not authorized. However, C exposes mint/burn/file/updatePrice as auth-protected too.
        // So we will test two general properties using only public surface:
        // - If updatePrice succeeds (does not revert), then c.latestPrice() equals the provided price and lastPriceUpdate() is non-zero and >= previous value.
        // - If updatePrice reverts when called from this contract, then it must be because msg.sender is not authorized (we cannot distinguish revert reasons),
        //   but we assert that in that case latestPrice and lastPriceUpdate remain unchanged.

        // Read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Try calling updatePrice and record whether it reverted
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule (single assert):
        // Either the call reverted and state did not change, or it succeeded and latestPrice equals price and timestamp advanced to >= beforeTs and is non-zero.
        assert(
            (reverted && afterPrice == beforePrice && afterTs == beforeTs)
            || (!reverted && afterPrice == price && afterTs >= beforeTs && afterTs != 0)
        );
    }

    receive() external payable {}
}

