contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking arbitrary addresses and an account/amount
    function run(address who, address spender, uint256 amount) public payable {
        require(true);

        // We will probe several view getters that should forward to the underlying share token.
        // For each call we capture whether it reverted using try/catch, and any returned values.
        bool nameReverted;
        string memory nameVal;
        try c.name() returns (string memory s) { nameReverted = false; nameVal = s; } catch { nameReverted = true; }

        bool symbolReverted;
        string memory symbolVal;
        try c.symbol() returns (string memory s2) { symbolReverted = false; symbolVal = s2; } catch { symbolReverted = true; }

        bool decimalsReverted;
        uint8 decimalsVal;
        try c.decimals() returns (uint8 d) { decimalsReverted = false; decimalsVal = d; } catch { decimalsReverted = true; }

        bool totalSupplyReverted;
        uint256 totalSupplyVal;
        try c.totalSupply() returns (uint256 ts) { totalSupplyReverted = false; totalSupplyVal = ts; } catch { totalSupplyReverted = true; }

        bool balanceReverted;
        uint256 balanceVal;
        try c.balanceOf(who) returns (uint256 b) { balanceReverted = false; balanceVal = b; } catch { balanceReverted = true; }

        bool allowanceReverted;
        uint256 allowanceVal;
        try c.allowance(who, spender) returns (uint256 a) { allowanceReverted = false; allowanceVal = a; } catch { allowanceReverted = true; }

        // General rule asserted: if name() call did NOT revert then symbol() and decimals() must also not revert,
        // and the returned name/symbol must not both be empty strings (at least one has non-zero length),
        // and decimals is within a reasonable uint8 range (0..255 always true but ensures we read it),
        // additionally if totalSupply/view balance/allowance reverted then name must have reverted as well
        // (i.e., either all basic ERC20 view probes succeed or name fails first).

        assert(
            // if name succeeded then symbol and decimals must have succeeded
            ((nameReverted == false) ? (symbolReverted == false && decimalsReverted == false) : true)
            // if any of the supply/balance/allowance views reverted then name must have reverted (observational consistency)
            && ((totalSupplyReverted || balanceReverted || allowanceReverted) ? nameReverted == true : true)
            // if name succeeded, at least one of name or symbol is non-empty
            && ((nameReverted == false) ? (bytes(nameVal).length + bytes(symbolVal).length > 0) : true)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We pass arbitrary values; msg.sender for calls to c will be this contract.
    function run(address receiver, address owner, uint256 assets, uint256 shares) public payable {
        require(true);

        // Capture whether state-changing functions revert when called by this contract but with a different owner/receiver.
        bool depositReverted;
        try c.deposit(assets, receiver) returns (uint256 s) { depositReverted = false; } catch { depositReverted = true; }

        bool mintReverted;
        try c.mint(shares, receiver) returns (uint256 a) { mintReverted = false; } catch { mintReverted = true; }

        bool withdrawReverted;
        try c.withdraw(assets, receiver, owner) returns (uint256 s2) { withdrawReverted = false; } catch { withdrawReverted = true; }

        bool redeemReverted;
        try c.redeem(shares, receiver, owner) returns (uint256 a2) { redeemReverted = false; } catch { redeemReverted = true; }

        // Also probe various view functions which should not revert when called.
        bool totalAssetsReverted;
        uint256 totalAssetsVal;
        try c.totalAssets() returns (uint256 tv) { totalAssetsReverted = false; totalAssetsVal = tv; } catch { totalAssetsReverted = true; }

        bool previewDepositReverted;
        uint256 previewDepositVal;
        try c.previewDeposit(assets) returns (uint256 pv) { previewDepositReverted = false; previewDepositVal = pv; } catch { previewDepositReverted = true; }

        bool previewMintReverted;
        uint256 previewMintVal;
        try c.previewMint(shares) returns (uint256 pv2) { previewMintReverted = false; previewMintVal = pv2; } catch { previewMintReverted = true; }

        bool maxDepositReverted;
        uint256 maxDepositVal;
        try c.maxDeposit(receiver) returns (uint256 mv) { maxDepositReverted = false; maxDepositVal = mv; } catch { maxDepositReverted = true; }

        // General rule:
        // If receiver != address(this) or owner != address(this) then the mutating entrypoints that require withApproval
        // must revert when called by this contract (since withApproval requires msg.sender == owner/receiver). Conversely,
        // the view preview/max/total functions should be callable (i.e., not revert). We assert this behavior for all inputs.
        bool requireApprovalExpectedForDeposit = (receiver != address(this));
        bool requireApprovalExpectedForMint = (receiver != address(this));
        bool requireApprovalExpectedForWithdraw = (owner != address(this));
        bool requireApprovalExpectedForRedeem = (owner != address(this));

        assert(
            // Mutating functions revert exactly when the withApproval condition would fail for this caller
            (requireApprovalExpectedForDeposit ? depositReverted == true : depositReverted == false)
            && (requireApprovalExpectedForMint ? mintReverted == true : mintReverted == false)
            && (requireApprovalExpectedForWithdraw ? withdrawReverted == true : withdrawReverted == false)
            && (requireApprovalExpectedForRedeem ? redeemReverted == true : redeemReverted == false)
            // Views do not revert
            && (totalAssetsReverted == false)
            && (previewDepositReverted == false)
            && (previewMintReverted == false)
            && (maxDepositReverted == false)
        );
    }

    receive() external payable { }
}

