        try c.withdraw(assets, receiver, owner) returns (uint256 s2) { withdrawReverted = false; } catch { withdrawReverted = true; }

        bool redeemReverted;
        try c.redeem(shares, receiver, owner) returns (uint256 a2) { redeemReverted = false; } catch { redeemReverted = true; }

        bool requestDepositReverted;
        try c.requestDeposit(assets, owner) { requestDepositReverted = false; } catch { requestDepositReverted = true; }

        bool requestRedeemReverted;
        try c.requestRedeem(shares, owner) { requestRedeemReverted = false; } catch { requestRedeemReverted = true; }

        bool decreaseDepositReverted;
        try c.decreaseDepositRequest(assets, owner) { decreaseDepositReverted = false; } catch { decreaseDepositReverted = true; }

        bool decreaseRedeemReverted;
        try c.decreaseRedeemRequest(shares, owner) { decreaseRedeemReverted = false; } catch { decreaseRedeemReverted = true; }

        // Probe view functions which should not revert: totalAssets, previewDeposit, previewMint, previewWithdraw, previewRedeem,
        // maxDeposit, maxMint, maxWithdraw, maxRedeem, convertToShares, convertToAssets.
        bool totalAssetsReverted; uint256 totalAssetsVal;
        try c.totalAssets() returns (uint256 tv) { totalAssetsReverted = false; totalAssetsVal = tv; } catch { totalAssetsReverted = true; }

        bool previewDepositReverted; uint256 previewDepositVal;
        try c.previewDeposit(assets) returns (uint256 pv) { previewDepositReverted = false; previewDepositVal = pv; } catch { previewDepositReverted = true; }

        bool previewMintReverted; uint256 previewMintVal;
        try c.previewMint(shares) returns (uint256 pv2) { previewMintReverted = false; previewMintVal = pv2; } catch { previewMintReverted = true; }

        bool previewWithdrawReverted; uint256 previewWithdrawVal;
        try c.previewWithdraw(assets) returns (uint256 pw) { previewWithdrawReverted = false; previewWithdrawVal = pw; } catch { previewWithdrawReverted = true; }

        bool previewRedeemReverted; uint256 previewRedeemVal;
        try c.previewRedeem(shares) returns (uint256 pr) { previewRedeemReverted = false; previewRedeemVal = pr; } catch { previewRedeemReverted = true; }

        bool maxDepositReverted; uint256 maxDepositVal;
        try c.maxDeposit(receiver) returns (uint256 mv) { maxDepositReverted = false; maxDepositVal = mv; } catch { maxDepositReverted = true; }

        bool maxMintReverted; uint256 maxMintVal;
        try c.maxMint(receiver) returns (uint256 mv2) { maxMintReverted = false; maxMintVal = mv2; } catch { maxMintReverted = true; }

        bool maxWithdrawReverted; uint256 maxWithdrawVal;
        try c.maxWithdraw(receiver) returns (uint256 mv3) { maxWithdrawReverted = false; maxWithdrawVal = mv3; } catch { maxWithdrawReverted = true; }

        bool maxRedeemReverted; uint256 maxRedeemVal;
        try c.maxRedeem(owner) returns (uint256 mv4) { maxRedeemReverted = false; maxRedeemVal = mv4; } catch { maxRedeemReverted = true; }

        bool convertToSharesReverted; uint256 convertToSharesVal;
        try c.convertToShares(assets) returns (uint256 cs) { convertToSharesReverted = false; convertToSharesVal = cs; } catch { convertToSharesReverted = true; }

        bool convertToAssetsReverted; uint256 convertToAssetsVal;
        try c.convertToAssets(shares) returns (uint256 ca) { convertToAssetsReverted = false; convertToAssetsVal = ca; } catch { convertToAssetsReverted = true; }

        // Expectation: for functions protected by withApproval, the call should succeed iff msg.sender == the owner/receiver parameter.
        bool senderIsReceiver = (address(this) == receiver);
        bool senderIsOwner = (address(this) == owner);

        // General rule assertion combining all observations.
        assert(
            // deposit/mint require msg.sender == receiver
            (depositReverted == (!senderIsReceiver))
            && (mintReverted == (!senderIsReceiver))
            // withdraw/redeem/requests/decreases require msg.sender == owner
            && (withdrawReverted == (!senderIsOwner))
            && (redeemReverted == (!senderIsOwner))
            && (requestDepositReverted == (!senderIsOwner))
            && (requestRedeemReverted == (!senderIsOwner))
            && (decreaseDepositReverted == (!senderIsOwner))
            && (decreaseRedeemReverted == (!senderIsOwner))

            // view functions must not revert
            && (totalAssetsReverted == false)
            && (previewDepositReverted == false)
            && (previewMintReverted == false)
            && (previewWithdrawReverted == false)
            && (previewRedeemReverted == false)
            && (maxDepositReverted == false)
            && (maxMintReverted == false)
            && (maxWithdrawReverted == false)
            && (maxRedeemReverted == false)
            && (convertToSharesReverted == false)
            && (convertToAssetsReverted == false)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising updatePrice behavior
    function run(uint128 price, address caller) public payable {
        require(caller != address(0), "caller nonzero");

        // ensure this contract is authorized to call auth-only functions on c
        // The constructor of C sets deployer (this test deployer) as ward, but checker deploys C and then this test.
        // So we first try to grant ourselves authorization by calling rely via c (will revert if not authorized).
        bool hadAuth;
        try c.rely(address(this)) {
            hadAuth = true;
        } catch {
            hadAuth = false;
        }

        // read price-related before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Now attempt to perform updatePrice either as this contract (if authorized) or via a simulated external caller.
        // We cannot change msg.sender to `caller`, so we only model two cases: this contract calls updatePrice (may revert if not auth)
        bool reverted;
        if (caller == address(this)) {
            // call as this contract
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // if caller is not this contract, we cannot make c see another msg.sender in this single transaction.
            // So we just perform a no-op call to mimic an unauthorized attempt: calling updatePrice will be from this contract,
            // so it must either succeed only if this contract is authorized. We set reverted flag accordingly by trying.
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule asserted:
        // If the call did not revert, then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTs.
        // If the call reverted, then both latestPrice and lastPriceUpdate must be unchanged.
        assert(
            (!reverted && afterPrice == price && afterTs >= beforeTs) ||
            (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

