    // We test that functions guarded by withApproval revert iff msg.sender != owner.
    // We pick deposit(uint256,address) which returns shares when approved.
    // The test calls deposit with two different owners: one equal to msg.sender (the test contract)
    // and one different. Because the InvMutTest contract is the caller, withApproval(owner)
    // requires msg.sender == owner. We observe success vs revert and the relation to owner equality.

    function run(uint256 assets, address ownerEqual, address ownerDifferent) public payable {
        // Precondition: ensure ownerDifferent != address(this) to make the test meaningful
        require(ownerDifferent != address(this));
        // Also ensure ownerEqual is address(this) to represent the allowed case
        require(ownerEqual == address(this));

        // First, call deposit with ownerEqual (which equals msg.sender) -> should NOT revert.
        bool okAllowed;
        uint256 sharesAllowed;
        try c.deposit(assets, ownerEqual) returns (uint256 s) {
            okAllowed = true;
            sharesAllowed = s;
        } catch {
            okAllowed = false;
            sharesAllowed = 0;
        }

        // Second, call deposit with ownerDifferent (which != msg.sender) -> should revert.
        bool okDenied;
        uint256 sharesDenied;
        try c.deposit(assets, ownerDifferent) returns (uint256 s2) {
            okDenied = true;
            sharesDenied = s2;
        } catch {
            okDenied = false;
            sharesDenied = 0;
        }

        // General rule: deposit succeeds exactly when owner == msg.sender.
        // Here ownerEqual == address(this) so allowed call should succeed (okAllowed == true),
        // and ownerDifferent != address(this) so denied call should revert (okDenied == false).
        // Also, when allowed succeeded, returned sharesAllowed must equal c.previewDeposit(assets)
        // called by the same msg.sender (view call uses msg.sender of this test contract).

        uint256 previewShares = c.previewDeposit(assets);

        assert(okAllowed && !okDenied && (sharesAllowed == previewShares));
    }

    // No Ether handling needed.
    receive() external payable {}
}

