contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: caller tries to call file with provided parameters
    // isAuthed indicates whether the InvMutTest contract has been granted auth on c before calling file
    function run(address newManager, bool isAuthed) public payable {
        require(newManager != address(0), "newManager nonzero");
        // Setup: if isAuthed, grant ourselves authorization by calling rely from the deployer ward.
        // The test harness deploys c and initially wards[msg.sender] = 1 for the deployer of c, not this contract.
        // But we cannot directly call rely unless we are authorized. To achieve authorization in a legal way,
        // when isAuthed==true we attempt to call c.file to set investmentManager to an innocuous address via a try/catch
        // using the current authorization: only existing ward (the original deployer of c) can call c.rely on this contract.
        // However the InvMutTest cannot assume any other account; instead we use the public mint/burn functions which are auth-protected
        // as a probe: try to call c.mint to see if we already are authorized (unlikely). If isAuthed==true we expect to be able to get auth by
        // calling c.rely - but we cannot. Therefore the only state change we can perform that affects auth is to use c.file which itself is auth-protected.
        // Given constraints, we implement the test as follows: try to call c.file and record whether it reverts. If call succeeds, assert that the public
        // getter investmentManager() equals newManager; if it reverts, assert that the getter is not equal to newManager.

        bool reverted;
        // perform the call and catch revert
        try c.file("investmentManager", newManager) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address observed = c.investmentManager();

        // General rule: successful call implies investmentManager changed to newManager; reverted call implies it did not change to newManager
        assert((!reverted && observed == newManager) || (reverted && observed != newManager));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: attempt to call file to set investmentManager to newManager
    function run(address newManager) public payable {
        require(newManager != address(0), "newManager nonzero");

        bool reverted;
        try c.file("investmentManager", newManager) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the public getter (returns InvestmentManagerLike but accessible as address via address(c.investmentManager()) is not allowed)
        // So read it by calling an external view that returns address: use address(c).balance is unrelated; instead cast via abi decoding of a staticcall.
        // However per constraints we may call the public getter directly; its type is InvestmentManagerLike, but Solidity allows reading it as address by using
        // address(c.investmentManager()) is not permitted here. Instead perform a low-level staticcall to the getter selector to obtain the address.

        // Prepare selector for investmentManager(): function investmentManager() public returns (InvestmentManagerLike)
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("investmentManager()"));
        // staticcall should succeed for a view; but if it fails treat as reverted getter (unlikely)
        address observedManager = address(0);
        if (ok && data.length >= 32) {
            // investmentManager getter returns an address padded to 32 bytes
            observedManager = abi.decode(data, (address));
        }

        // General rule: if the file call succeeded then getter equals newManager; if file call reverted then getter is not equal to newManager
        assert((!reverted && observedManager == newManager) || (reverted && observedManager != newManager));
    }

    receive() external payable {}
}

