contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function as required
    function run(address caller, uint128 price) public payable {
        require(caller != address(0));

        // Make this contract authorized (wards[msg.sender] = 1) by calling rely in constructor-equivalent context:
        // c was deployed fresh with msg.sender authorized (the deployer). The InvMutTest is deployed by that deployer,
        // but here run() is called by the checker (externally). We need to toggle authorization so that this contract
        // (address(this)) is authorized to call updatePrice. To do that we ask the original deployer (who is ward) to
        // rely this test contract. The only way to perform that is to call c.rely(address) from this contract, but that
        // will require this contract to already be authorized. So instead we observe two cases:
        // - If this contract is already authorized, updatePrice should succeed and set latestPrice and lastPriceUpdate.
        // - If not authorized, updatePrice must revert.
        // We'll attempt the call and record whether it reverted, then assert the corresponding postcondition.

        // Read pre-values that are public
        uint128 beforePrice = c.latestPrice();
        uint256 beforeLastUpdate = c.lastPriceUpdate();

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterLastUpdate = c.lastPriceUpdate();

        // General rule:
        // If the call reverted then state must be unchanged (latestPrice and lastPriceUpdate unchanged).
        // If the call did not revert then latestPrice equals the supplied price and lastPriceUpdate is >= beforeLastUpdate
        // and nonzero (block.timestamp when called is nonzero) — we check > 0. We also ensure that when successful,
        // either price changed to the new value or it was already equal (idempotent call allowed).
        assert(
            reverted
            ? (afterPrice == beforePrice && afterLastUpdate == beforeLastUpdate)
            : (afterPrice == price && afterLastUpdate >= beforeLastUpdate && afterLastUpdate > 0)
        );
    }

    receive() external payable {}
}

