    // single public test function: try to call mint or burn on c as the contract itself
    // parameters: doMint selects which function to call; target is the address passed to mint/burn; amount is the amount
    function run(bool doMint, address target, uint256 amount) public payable {
        require(target != address(0), "target-nonzero");

        // Ensure this contract is authorized on c before invoking mint/burn by using c.rely from constructor of C
        // The deployment of C sets wards[msg.sender]=1 for its deployer; but here InvMutTest is not that deployer.
        // So first attempt to have c.rely(address(this)) must be done under the auth modifier. We cannot become authorized
        // unless c already authorized us. To create a meaningful rule we instead assert that if the call succeeds, authorization is preserved.

        // Call mint or burn and record whether it reverted.
        bool reverted;
        try c.mint(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If doMint was false, instead try burn (separate try-catch to ensure top-level state-changing calls)
        if (!doMint) {
            bool reverted2;
            try c.burn(target, amount) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            // final assertion must be a general relation: if burn succeeded then this contract remains authorized; otherwise no guarantee
            // We observe wards via the public getter wards(address)
            uint256 wardAfter = c.wards(address(this));
            // If burn succeeded (reverted2 == false) then wardAfter must be 1; otherwise no requirement.
            assert(reverted2 || wardAfter == 1);
            return;
        }

        // For the mint branch: if mint succeeded then wards[this]==1
        uint256 wardAfterMint = c.wards(address(this));
        assert(reverted || wardAfterMint == 1);
    }

    receive() external payable {}
}

