    function run(uint128 price, address maybeWard) public payable {
        require(true);

        // Try to make maybeWard an authorized ward by calling rely from this contract if we are already authorized.
        // The freshly deployed C set the deployer (the checker) as ward, not this contract. So relying may revert.
        bool relied;
        try c.rely(maybeWard) {
            // If this contract was authorized, the call succeeds and maybeWard becomes a ward
            relied = true;
        } catch {
            relied = false;
        }

