        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Now attempt to call updatePrice from this contract using maybeWard as the target value must be set by a ward.
        // We want to test two behaviours: if this contract is authorized it can call updatePrice and values change accordingly;
        // otherwise the call must revert.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // The general rule to assert:
        // - If updatePrice succeeded (not reverted) then latestPrice equals the provided price and lastPriceUpdate is >= beforeTimestamp.
        // - If updatePrice reverted then both latestPrice and lastPriceUpdate remain equal to their before values.
        assert((!reverted && afterPrice == price && afterTimestamp >= beforeTimestamp) || (reverted && afterPrice == beforePrice && afterTimestamp == beforeTimestamp));
    }

    receive() external payable {}
}

