contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that deposit(...) forwards to investmentManager.processDeposit and succeeds exactly when it doesn't revert.
    // Parameters: assets to deposit and receiver address.
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // Capture some observable pre-state
        uint256 beforeTotalAssets = c.totalAssets();

        // Attempt the deposit and record whether it reverted
        bool reverted;
        uint256 sharesReturned;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            sharesReturned = shares;
        } catch {
            reverted = true;
            sharesReturned = 0;
        }

        // After call, read observable state again
        uint256 afterTotalAssets = c.totalAssets();

        // General rule (single assert): If deposit succeeded then totalAssets must be >= beforeTotalAssets
        // and sharesReturned must equal the contract's convertToShares(assets) OR at least not be zero when assets > 0.
        // We express a conservative general invariant: success implies totalAssets did not decrease and either
        // sharesReturned is the convertToShares(assets) view or assets==0 implies sharesReturned==0.
        // This ties the mutating deposit behavior to public views of the contract.
        assert(
            reverted
            || (
                afterTotalAssets >= beforeTotalAssets
                && (assets == 0 ? sharesReturned == 0 : (sharesReturned == c.convertToShares(assets) || sharesReturned > 0))
            )
        );
    }

    receive() external payable {}
}

